import { defineLegalText } from "./index";
import type { AgreementFields } from "./operatingAgreement";

/**
 * The Legal Body Charter: a supplement to the company's operating agreement, for one agent. It is
 * the same text whichever door the company came in by, the declared door or the formed door, and it
 * names the company as the October agreement does.
 *
 * It is a version of the agreement text, under the agreement's id. It has the agreement's string
 * fields and one more, `scheduleA`: the grants in force, as wording the server renders from the
 * guardian's choices (`grant.ts`). No one types it. `render` fills every placeholder in one pass,
 * so a Schedule A that holds a placeholder stays that text.
 *
 * It has four versions, each a full text of its own. The version names are not consecutive: the
 * code holds drafts 1, 2, 4 and 5. The Schedule A wording `grant.ts` writes is the one drafts 4
 * and 5 state.
 *
 * All four versions are defined and pinned here. No door serves any of them: new agreements are
 * still made under the October version.
 */
export interface CharterFields extends AgreementFields {
  scheduleA: string;
}

